// 프로그래밍 과제 픽스처 (한국어 설명 + 코드). 코드는 코드펜스로 묶인 한 덩어리를 한 문장처럼 다룬다.
const CODE = [
  '```python',
  'def binary_search(arr, target):',
  '    low, high = 0, len(arr) - 1',
  '    while low <= high:',
  '        mid = (low + high) // 2',
  '        if arr[mid] == target:',
  '            return mid',
  '        elif arr[mid] < target:',
  '            low = mid + 1',
  '        else:',
  '            high = mid - 1',
  '    return -1',
  '```',
].join('\n');

const LINEAR = [
  '```python',
  'def linear_search(values, wanted):',
  '    for index, value in enumerate(values):',
  '        if value == wanted:',
  '            return index',
  '    return -1',
  '```',
].join('\n');

